races.forEach((race,offset)=>{const index=newRaceStart+offset;if(RACES.length!==index)throw Error('Unexpected race catalog order');RACES.push(race.data);WorldLore.raceWays.push(race.ways);LifeContent.races.push(race.daily);raceTraits[index]={kind:race.kind,appearance:race.appearance};});
