 const labels={education:'การเรียนรู้',family:'ครอบครัว',joy:'ความสุข',health:'สุขภาพ',career:'อาชีพ',explore:'สำรวจโลก',magic:'เวทมนตร์','scholar-research':'วิจัยความรู้','artisan-craft':'งานช่าง',performer:'การแสดง',community:'ชุมชน','goblin-diplomacy':'ไมตรีกอบลิน','dragon-hoard':'ขุมทรัพย์มังกร','dragon-guard':'คุ้มครองอาณาเขต','demon-pact':'พันธสัญญาปีศาจ','demon-dominion':'ราชสำนักปีศาจ','merchant-trade':'การค้า'};
