 function reason(s,p,checkRoom=false){const r=p.requirements||{};if(typeof Ecology!=='undefined'&&!Ecology.projectAllowed(s,p.id))return 'วิธีทำเป้าหมายนี้ไม่เหมาะกับถิ่นและรูปกายของคุณ';if(s.dead)return 'ชีวิตนี้สิ้นสุดแล้ว';if(!s.accepted)return 'เริ่มชีวิตก่อนเลือกเป้าหมาย';if(bio(s)<p.minAge)return 'เริ่มได้เมื่อเติบโตเทียบวัย '+p.minAge+' ปี';if(Number.isInteger(r.race)&&s.race!==r.race)return 'เป็นเส้นทางเฉพาะ'+RACES[r.race][0];if(r.demon&&!Species.isDemon(s.race))return 'เป็นเส้นทางของเผ่าปีศาจ';if(r.family&&s.heritage?.familyId!==r.family)return 'เป็นเส้นทางเฉพาะครอบครัวผู้กล้า';if(r.job&&s.job===null)return 'ต้องมีอาชีพก่อนเริ่ม';if(r.business&&!s.livelihood?.business)return 'ต้องมีกิจการที่ยังเปิดอยู่';if(r.anyInventory&&!r.anyInventory.some(id=>s.lifeChoices?.inventory?.includes(id)))return 'ต้องมี'+r.anyInventory.map(id=>LifeChoices.shop.find(x=>x.id===id)?.name||id).join(' หรือ ');const saved=s.projects?.active?.id===p.id?s.projects.active:s.projects?.paused?.find(a=>a.id===p.id),anchor=saved?.kingdom??(r.business?s.livelihood?.business?.kingdom:s.kingdom);if(p.anchored&&Number.isInteger(anchor)&&anchor!==s.kingdom)return 'เป้าหมายนี้อยู่ใน'+KINGDOMS[anchor][0]+' กลับไปที่นั่นก่อนจึงจะลงมือต่อได้';if(checkRoom&&!room(s))return s.calendar?.pending?'ตอบเหตุการณ์สำคัญก่อน':'อ่านผลการตัดสินใจก่อน';return ''}
 function costQuote(s,p){return typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s)?{value:Math.max(1,p.costPerQuarter/20),unit:'กำลังแหล่งถิ่น'}:{value:p.costPerQuarter,unit:'ทอง'}}
