  const scale=delta*4,nativeCost=typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s)?costQuote(s,p).value*scale:0,cost=nativeCost?0:Math.round(p.costPerQuarter*scale*100)/100;if(nativeCost&&s.raceDrives.resource<nativeCost){if(a.lastNote!==Math.floor(s.age)){a.lastNote=Math.floor(s.age);return write(s,'แหล่งถิ่นที่ยังต้องฟื้น',[p.name+'ต้องใช้กำลังจากแหล่งดำรงชีวิต คุณพักส่วนที่ฝืนไว้ก่อนและยังกลับมาทำต่อจากบทเดิมได้'],Ecology.profile(s).scene)}return null}if(s.gold<cost){if(a.lastNote!==Math.floor(s.age)){a.lastNote=Math.floor(s.age);return write(s,'ทุนที่ยังต้องกันไว้ก่อน',[p.name+'ต้องใช้วัสดุหรือค่าเดินทางเล็กน้อย แต่เงินที่มีไม่พอ คุณหยุดการใช้จ่ายของเป้าหมายไว้ก่อน','ความคืบหน้าที่ทำแล้วไม่ได้หายไป และไม่มีหนี้ถูกสร้างให้โดยอัตโนมัติ'],p.scene)}return null}
