 function decorate(s,event){if(typeof Ecology!=='undefined'&&Ecology.projectInfo(s,event?.projectOnly))return Ecology.decorateProject(s,event);if(!event?.projectOnly)return event;const a=s.projects?.active,canonical=EVENTS.find(e=>e.id===event.id&&e.projectOnly===event.projectOnly);if(!a||!canonical||a.id!==event.projectOnly||a.stage!==event.projectStage)return event;const prior=a.decisions.filter(d=>d.stage<event.projectStage),lastStage=event.projectStage-1,earlier=prior.filter(d=>d.stage===lastStage),selected=earlier.filter(d=>d.success).at(-1)||earlier.at(-1);if(!selected)return {...event,text:canonical.text};const bridge=selected.success?'ก่อนหน้านี้คุณเลือก “'+selected.choice+'” ผลจากวิธีนั้นเป็นจุดเริ่มของบทนี้ ':'บทก่อนหน้าคุณลอง “'+selected.choice+'” และปรับแผนหลังความผิดพลาด ก่อนเดินเรื่องต่อ ';return {...event,text:(bridge+canonical.text).slice(0,1400)}}
 function eventContext(s,base){const a=ensure(s).active;return a?{...base,npc:a.cast.name,relativeId:a.cast.memberId||base.relativeId}:base}
