 for(const p of catalog)p.stages.forEach((stage,index)=>EVENTS.push({id:'project-'+p.id+'-'+index,title:stage.title,text:stage.text,min:p.minAge,choices:stage.choices,scene:stage.scene,projectOnly:p.id,projectStage:index,lifeOpportunity:true,once:true}));
