 function matches(s,e){if(!e.bondOnly)return true;const b=ensure(s),d=spec.find(x=>x[0]===e.bondOnly.story),st=b.stories[e.bondOnly.story],p=d&&actor(s,d[1]),r=p&&resolved(s,p);return !!st&&!st.ended&&st.step===e.bondOnly.step&&bio(s)>=st.readyBio&&!!r?.alive&&!!r?.met}
 function eventContext(s,e,base={}){if(!e.bondOnly)return base;const d=spec.find(x=>x[0]===e.bondOnly.story),p=d&&actor(s,d[1]);if(!p)return base;const r=resolved(s,p);return {...base,npc:r.name,npcRace:r.race,npcAge:Engine.ageEquivalent(r.age,r.race),relative:r.name,relativeId:p.memberId||'',bondId:p.id}}
 function decorate(s,e){if(!e.bondOnly)return e;if(typeof Ecology!=='undefined')e=Ecology.decorateBond(s,e);const st=ensure(s).stories[e.bondOnly.story],prior=st?.choices.at(-1);return {...e,text:prior?'ครั้งก่อนคุณเลือก “'+prior.label+'” '+(e.bondOnly.step===2?'วันนี้เรื่องนั้นเดินทางมาถึงอีกบทหนึ่ง ':'')+e.text:e.text}}
 function observe(s,e,c,ok){if(!e.bondOnly)return;const b=ensure(s),d=spec.find(x=>x[0]===e.bondOnly.story),st=b.stories[e.bondOnly.story],p=d&&actor(s,d[1]);if(!st||!p||st.step!==e.bondOnly.step)return;trust(s,p,ok?(c.bondTrust||0):-2);if(ok&&c.bondMode==='close')p.support=Math.min(30,(p.support||0)+1);if((c.bondTrust||0)<0)p.grievance=Math.min(10,p.grievance+1);const text='คุณเลือก'+c.label+' ในเรื่อง “'+e.title+'”';remember(s,p,text);st.choices.push({label:c.label,age:s.age,mode:c.bondMode||'quiet'});st.choices.length=Math.min(3,st.choices.length);st.step++;st.readyBio=bio(s)+(e.bondOnly.step===0?2:3);if(st.step>=3)st.ended=true;
  if(ok&&c.promise){const previous=b.promises.find(x=>x.actor===p.id&&x.state==='pending');if(!previous){b.promises.push({id:e.id,actor:p.id,text:c.promise.text,action:c.promise.action,dueBio:bio(s)+1.5,dueAge:Math.ceil(Engine.ageFromEquivalent(bio(s)+1.5,s.race)),state:'pending'});if(b.promises.length>16)b.promises.splice(b.promises.findIndex(x=>!['pending','fulfilled'].includes(x.state)),1);}}
  if(ok&&c.moveFriend){p.kingdom=(s.kingdom+1+hash(s.seed,e.id.length)%Math.max(1,KINGDOMS.length-1))%KINGDOMS.length;p.distance=true;}
  if(ok&&c.reconcile){p.grievance=0;}if(ok&&st.ended){const close=st.choices.filter(x=>x.mode==='close').length;if(close>=2){s.bond=clamp(s.bond+3);trust(s,p,3);const note=resolved(s,p).name+'เรียกเรื่อง “'+d[3]+'” ว่าเรื่องของเราสองคน';remember(s,p,note);}else if(st.choices.filter(x=>x.mode==='distance').length>=2){trust(s,p,-2);remember(s,p,'คุณกับเขาเลือกคนละทางในเรื่อง “'+d[3]+'” แต่ยังจำว่าเริ่มต้นด้วยกันอย่างไร');}}
 }
 function memorial(s){const b=ensure(s),people=list(s).filter(p=>p.memories.length);if(s.dead)return people.filter(p=>p.alive).sort((a,b)=>b.trust-a.trust).slice(0,4).map(p=>({name:p.name,role:p.role,race:p.race,text:p.memories[0].text,age:p.memories[0].age}));return b.memorials.slice()}
 function sync(s,d){const b=ensure(s);for(const p of b.cast){const r=resolved(s,p);if(p.memberId||!r.met)continue;let old=d.people.find(x=>x.id===p.id);if(!old&&d.people.length<12){old={id:p.id};d.people.push(old)}if(old)Object.assign(old,{name:r.name,role:r.role,trust:r.trust,race:r.race,bondId:p.id,alive:r.alive})}}
 function family(s){const b=ensure(s);for(const member of s.household?.members||[]){if(b.cast.length>=16||b.cast.some(p=>p.memberId===member.id))continue;const h=hash(s.seed,member.id.length*37+b.cast.length),id='kin:'+member.id;b.cast.push({id,memberId:member.id,name:member.name,race:member.race,role:member.role,meetBio:0,ageAtBirth:member.ageAtBirth,lifeExpectancy:member.lifeExpectancy,alive:member.alive,trust:member.trust,look:member.look,kingdom:s.homeKingdom??s.kingdom,dream:typeof Ecology==='undefined'?dreams[h%dreams.length]:Ecology.bondDream(member.race,h,dreams[h%dreams.length]),preference:typeof Ecology==='undefined'?preferences[(h>>>4)%preferences.length]:Ecology.bondPreference(member.race,h,preferences[(h>>>4)%preferences.length]),trait:traits[(h>>>8)%traits.length],memories:[],announced:true,distance:false,lastMoment:-1,lossRecorded:false,grievance:0,support:0,dreamStage:0,dreamReadyBio:0})}}
 function valid(s){const b=s.bonds;if(b===undefined)return true;const num=(n,a,b)=>Number.isFinite(n)&&n>=a&&n<=b,int=(n,a,b)=>Number.isInteger(n)&&num(n,a,b),str=(x,max)=>typeof x==='string'&&x.length<=max,ids=['guardian','relative','friend','mentor','rival'];return !!b&&b.version===1&&int(b.lastQuarter,-1,s.calendar?.count??0)&&int(b.lastAction,-1,q(s))&&num(b.lastBio,0,bio(s)+.001)&&num(b.lastMomentBio,0,bio(s)+.001)&&Array.isArray(b.cast)&&b.cast.length>=4&&b.cast.length<=16&&new Set(b.cast.map(x=>x?.id)).size===b.cast.length&&b.cast.every(p=>p&&(ids.includes(p.id)||/^kin:[a-z0-9-]{1,70}$/.test(p.id))&&(p.memberId===null||str(p.memberId,80))&&str(p.name,99)&&int(p.race,0,RACES.length-1)&&str(p.role,200)&&num(p.meetBio,0,18)&&num(p.ageAtBirth,-10000,10000)&&num(p.lifeExpectancy,1,10000)&&typeof p.alive==='boolean'&&num(p.trust,0,100)&&p.look&&int(p.look.hair,0,30)&&int(p.look.coat,0,30)&&int(p.look.eyes,0,30)&&int(p.kingdom,0,KINGDOMS.length-1)&&(dreams.includes(p.dream)||typeof Ecology!=='undefined'&&Ecology.nativeDreams.includes(p.dream))&&(preferences.includes(p.preference)||typeof Ecology!=='undefined'&&[0,1,2].some(n=>Ecology.bondPreference(p.race,n,'')===p.preference))&&traits.includes(p.trait)&&typeof p.announced==='boolean'&&typeof p.distance==='boolean'&&typeof p.lossRecorded==='boolean'&&(p.deathAge===undefined||num(p.deathAge,0,100000))&&int(p.grievance,0,10)&&int(p.support??0,0,30)&&int(p.dreamStage??0,0,3)&&num(p.dreamReadyBio??0,0,20000)&&int(p.lastMoment,-1,20000)&&Array.isArray(p.memories)&&p.memories.length<=8&&p.memories.every(m=>m&&num(m.age,0,s.age)&&str(m.text,600)))&&b.stories&&Object.keys(b.stories).length===spec.length&&spec.every(([id])=>{const x=b.stories[id];return x&&int(x.step,0,3)&&num(x.readyBio,0,20000)&&typeof x.ended==='boolean'&&Array.isArray(x.choices)&&x.choices.length===x.step&&x.choices.every(c=>c&&str(c.label,150)&&num(c.age,0,s.age)&&['close','distance','quiet'].includes(c.mode))})&&Array.isArray(b.promises)&&b.promises.length<=16&&new Set(b.promises.map(p=>p?.id)).size===b.promises.length&&b.promises.every(p=>p&&str(p.id,100)&&b.cast.some(x=>x.id===p.actor)&&str(p.text,200)&&actions.some(a=>a.id===p.action)&&num(p.dueBio,0,20000)&&num(p.dueAge,0,10000)&&['pending','fulfilled','kept','broken','cancelled'].includes(p.state))&&Array.isArray(b.memorials)&&b.memorials.length<=12&&b.memorials.every(m=>m&&str(m.name,99)&&str(m.role,200)&&int(m.race,0,RACES.length-1)&&str(m.text,600)&&num(m.age,0,s.age))}
